D.glossary = [
  ['Adjuster', 'Stainless-steel or cobalt rod normally in-core to flatten the flux; withdrawn for xenon override.'],
  ['Annulus gas', 'Dry CO₂ between pressure tube and calandria tube; insulation and leak detection.'],
  ['Bundle', 'Fuel assembly ≈ 0.5 m long with 37 elements; 12 per channel.'],
  ['Calandria', 'Low-pressure vessel holding the moderator; pierced by the fuel channels.'],
  ['CCP – critical channel power', 'Channel power at which the fuel first experiences dryout, with the header conditions held fixed and flow allowed to respond.'],
  ['CHF – critical heat flux', 'Heat flux at which the liquid film on the sheath is lost (dryout) and heat transfer deteriorates.'],
  ['CPPF – channel power peaking factor', 'Largest ratio of an instantaneous channel power to its time-average reference value; caused by the refuelling ripple. Used to calibrate ROP detectors.'],
  ['CPR – critical power ratio', 'CCP divided by actual channel power; the margin to dryout of a channel.'],
  ['Creep (diametral)', 'Irradiation-induced permanent expansion of the pressure-tube diameter under hoop stress.'],
  ['EFPY / EFPH', 'Effective full-power years / hours – the measure of accumulated irradiation.'],
  ['End fitting', 'Stainless-steel extension at each end of a pressure tube carrying the feeder connection and closure.'],
  ['Feeder', 'Individual pipe connecting one end of a channel to a header.'],
  ['Figure-of-eight', 'Loop layout in which coolant passes through the core twice per circuit, in opposite directions.'],
  ['FP', 'Full power.'],
  ['Header (RIH / ROH)', 'Reactor inlet / outlet header: manifold feeding or collecting 95 channels.'],
  ['LISS', 'Liquid injection shutdown system – Shutdown System 2.'],
  ['LOCA / LOECC', 'Loss-of-coolant accident / loss of emergency core cooling.'],
  ['LOR', 'Loss of regulation – the regulating system fails in a way that adds reactivity.'],
  ['LZC', 'Liquid zone controller – light-water compartment used for bulk and spatial control.'],
  ['MCA', 'Mechanical control absorber.'],
  ['mk', 'Milli-k: unit of reactivity, Δk/k × 1000. β ≈ 5.8 mk in a CANDU.'],
  ['Moderator', 'Heavy water in the calandria that slows neutrons; separate from the coolant.'],
  ['OID', 'Onset of intermittent dryout – the conservative criterion used for CCP.'],
  ['PHTS / HTS', 'Primary heat transport system.'],
  ['Quality', 'Mass fraction of vapour in a two-phase mixture; “thermodynamic quality” can be negative for sub-cooled liquid.'],
  ['RIHT', 'Reactor inlet header temperature.'],
  ['ROP / NOP', 'Regional (or neutron) overpower protection: in-core detector trips on both shutdown systems that prevent dryout.'],
  ['RRS', 'Reactor regulating system.'],
  ['SDS1 / SDS2', 'Shutdown System 1 (shutoff rods) / Shutdown System 2 (poison injection).'],
  ['Setback / Stepback', 'Regulating-system ramped / stepped power reductions.'],
  ['Thermosyphoning', 'Natural circulation between the core and the elevated steam generators.'],
  ['TSP', 'Trip set-point.'],
  ['Void reactivity', 'Reactivity change when coolant is replaced by steam – positive in CANDU.'],
  ['Xenon-135', 'Fission-product poison (σ ≈ 3 × 10⁶ b) whose concentration peaks ≈ 10 h after a power reduction.']
];

D.quiz = [
  { q: 'Why does channel flow decrease when channel power increases, even though the pumps keep running?', a: ['The pumps slow down automatically', 'Boiling increases the two-phase pressure drop in the channel and outlet feeder while the header-to-header ΔP stays fixed', 'The inlet feeder contracts thermally', 'The moderator absorbs the flow'], c: 1, why: 'All 380 channels share the same inlet and outlet headers. More vapour means more friction and acceleration loss for the same mass flow, so flow must drop until the channel ΔP again equals the header ΔP. This “flow–power coupling” is why critical channel power is lower than a fixed-flow calculation would suggest.' },
  { q: 'What does pressure-tube diametral creep do to the margin to dryout?', a: ['Improves it, because the flow area is bigger', 'Nothing', 'Reduces it: coolant by-passes the bundle through the gap at the top', 'Reduces it because the tube wall gets hotter'], c: 2, why: 'Total channel flow rises a little, but the flow that matters – through the sub-channels between elements – falls, and the enthalpy imbalance grows. CHF drops, so CCP drops.' },
  { q: 'The ROP trip set-point must be reduced as the plant ages mainly because…', a: ['Detectors lose sensitivity', 'Critical channel powers fall (creep, higher inlet temperature, lower flow)', 'Xenon increases', 'The fuel burnup increases'], c: 1, why: 'TSP is derived from CCP. Anything that lowers CCP – creep, steam-generator fouling raising RIHT, feeder roughening lowering flow – lowers the power at which dryout would start, so the trip must act earlier.' },
  { q: 'Why are ROP detectors calibrated to (reactor power × CPPF) rather than to reactor power?', a: ['To make them read high for conservatism against the refuelling ripple', 'Because platinum detectors over-read', 'To compensate for xenon', 'To match the turbine power'], c: 0, why: 'The trip set-point analysis uses time-average channel powers. Real channels are up to ≈ 8–10 % above their reference just after refuelling; multiplying the detector calibration by CPPF restores the margin.' },
  { q: 'Coolant voiding in a CANDU adds positive reactivity. Which design features make this acceptable?', a: ['A thick pressure vessel', 'Two independent fast shutdown systems, a long prompt-neutron lifetime and a small void worth per loop', 'Boron in the coolant', 'Negative moderator coefficient'], c: 1, why: 'Dividing the core into two loops halves the void inserted by a break; Λ ≈ 0.9 ms slows the excursion; SDS1 and SDS2 each terminate it within ≈ 1–2 s.' },
  { q: 'What sets the reactor inlet header temperature?', a: ['Pressurizer heaters', 'Steam-generator secondary pressure and heat-transfer capability (UA)', 'Moderator temperature', 'Feeder size'], c: 1, why: 'Coolant leaves the steam generator a few degrees above secondary saturation temperature. Higher steam pressure or a fouled steam generator raises RIHT.' },
  { q: 'After a trip from full power, how long does the operator have to restart before xenon “poisons out” the reactor?', a: ['About 30–35 minutes', '2 minutes', '10 hours', 'No limit'], c: 0, why: 'Withdrawing all adjusters gives ≈ +15 mk, enough to override the xenon build-up for roughly half an hour. After that the reactor cannot be made critical for ≈ 35–40 h.' },
  { q: 'What is the heat sink if a LOCA occurs and ECC fails?', a: ['The containment dousing spray', 'The steam generators', 'The moderator, through pressure-tube/calandria-tube contact', 'The end shields'], c: 2, why: 'Hot pressure tubes deform into contact with the calandria tubes, which are cooled by the sub-cooled moderator.' },
  { q: 'An isotope-production target (neutron absorber) is driven into one side of the core at power. What happens first?', a: ['The reactor trips on log rate', 'Local flux is depressed, bulk power dips, zone controllers drain to restore power and re-balance the tilt', 'Nothing measurable', 'Coolant void increases'], c: 1, why: 'The regulating system sees a small negative reactivity and a zone power imbalance. It lowers light-water levels – most in the zones near the target.' },
  { q: 'Why are feeders of different sizes used?', a: ['To reduce heavy-water inventory', 'To match each channel’s flow to its power so exit enthalpies are similar', 'For seismic reasons', 'To make fuelling easier'], c: 1, why: 'Peripheral channels produce less than half the power of central ones; smaller feeders (and orifices) throttle their flow so that no pump head is wasted and outlet-header conditions are uniform.' },
  { q: 'Which shutdown-system trip is expected to act first in a large LOCA?', a: ['Low steam-generator level', 'High rate of log neutron power / high neutron power', 'Low pressurizer level', 'High moderator temperature'], c: 1, why: 'The void-driven power pulse develops within tenths of a second, long before process parameters move.' },
  { q: 'Raising the outlet-header pressure set-point at constant power would…', a: ['Lower the saturation temperature', 'Raise saturation temperature, reducing exit quality and void', 'Have no effect', 'Increase flow by 50 %'], c: 1, why: 'More sub-cooling at the inlet for the same inlet temperature means boiling starts later. Hoop stress – and creep rate – would also rise, which is one reason the pressure is not increased.' }
];
